def solve(n):
    N = 2 * n + 1
    coins = [1] * N  # 1 for Heads, 0 for Tails
    # Coins are indexed 0 to N-1. P_k = k(k+1)/2.
    # Using 0-indexing for coins, so P_k = k(k+1)/2 - 1 (mod N)
    # But let's stick to 1-indexing for positions and use (P_k - 1) % N
    for k in range(1, 2 * n + 2):
        pos = (k * (k + 1) // 2) % N
        if pos == 0:
            pos = N
        # Flip coin at position pos
        coins[pos - 1] = 1 - coins[pos - 1]
    return sum(1 for c in coins if c == 0)

